{-| @Backend.Runtime.Kernel.Html — a `Std.Html.Html` page rendered in one
    pass into one growing buffer, with escaping fused into the copy. -}
module Pudu.Backend.Runtime.Kernel.Html (htmlKernelParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
htmlKernelParts :: [(Text, [Text], [Text])]
htmlKernelParts =
  [ ("html_render", ["array", "text", "text_allocate", "memory_failure", "html_marks"],
      [ "/* The page is written straight into the text it becomes: a growing text"
      , "   owner, sized first from the length this thread rendered last. */"
      , "typedef struct { pudu_text_owner *owner; size_t length, capacity; int text_tag, fragment_tag, trusted_tag; void (*drop)(pudu_box *); } pudu_html_writer;"
      , "static _Thread_local size_t pudu_html_last_length;"
      , "static void pudu_html_grow(pudu_html_writer *out, size_t capacity) {"
      , "  if (capacity > (size_t)PTRDIFF_MAX - sizeof(pudu_text_owner)) pudu_memory_failure();"
      , "  out->owner = realloc(out->owner, sizeof(pudu_text_owner) + capacity);"
      , "  if (out->owner == NULL) pudu_memory_failure();"
      , "  out->capacity = capacity;"
      , "}"
      , "static void pudu_html_write(pudu_html_writer *out, const void *bytes, size_t length) {"
      , "  if (length > out->capacity - out->length) {"
      , "    size_t capacity = out->capacity;"
      , "    if (length > SIZE_MAX - out->length) pudu_memory_failure();"
      , "    while (capacity < out->length + length) capacity = capacity > SIZE_MAX / 2 ? out->length + length : capacity * 2;"
      , "    pudu_html_grow(out, capacity);"
      , "  }"
      , "  if (length != 0) memcpy(out->owner->bytes + out->length, bytes, length);"
      , "  out->length += length;"
      , "}"
      , "/* Text as `Str.escapeHtml` writes it: runs without a marked byte go whole. */"
      , "static void pudu_html_escape(pudu_html_writer *out, pudu_text text) {"
      , "  size_t from = 0;"
      , "  for (size_t i = pudu_html_skip(text.bytes, 0, text.length); i < text.length; i = pudu_html_skip(text.bytes, i + 1, text.length)) {"
      , "    const char *entity;"
      , "    size_t width;"
      , "    switch (text.bytes[i]) {"
      , "      case '&': entity = \"&amp;\"; width = 5; break;"
      , "      case '<': entity = \"&lt;\"; width = 4; break;"
      , "      case '>': entity = \"&gt;\"; width = 4; break;"
      , "      case '\"': entity = \"&quot;\"; width = 6; break;"
      , "      case '\\'': entity = \"&#39;\"; width = 5; break;"
      , "      default: continue;"
      , "    }"
      , "    pudu_html_write(out, text.bytes + from, i - from);"
      , "    pudu_html_write(out, entity, width);"
      , "    from = i + 1;"
      , "  }"
      , "  pudu_html_write(out, text.bytes + from, text.length - from);"
      , "}"
      , "/* A letter, then letters, digits, '-', '_', '.' or ':'; every other byte,"
      , "   a non-ASCII scalar's included, fails. */"
      , "static int pudu_html_name(pudu_text text) {"
      , "  if (text.length == 0) return 0;"
      , "  for (size_t i = 0; i < text.length; ++i) {"
      , "    unsigned char byte = text.bytes[i];"
      , "    int letter = (byte >= 'a' && byte <= 'z') || (byte >= 'A' && byte <= 'Z');"
      , "    if (i == 0 ? !letter : !(letter || (byte >= '0' && byte <= '9') || byte == '-' || byte == '_' || byte == '.' || byte == ':')) return 0;"
      , "  }"
      , "  return 1;"
      , "}"
      , "/* A valid name beginning with 'on' in any case names a handler. */"
      , "static int pudu_html_handler(pudu_text text) {"
      , "  return text.length >= 2 && (text.bytes[0] | 32) == 'o' && (text.bytes[1] | 32) == 'n';"
      , "}"
      , "/* The void elements, grouped by length: the names of length n sit"
      , "   back to back in voids[n]. */"
      , "static int pudu_html_void(pudu_text text) {"
      , "  static const char *const voids[] = {\"\", \"\", \"brhr\", \"colimgwbr\", \"areabaselinkmeta\", \"embedinputtrack\", \"source\"};"
      , "  const char *names;"
      , "  if (text.length < 2 || text.length > 6) return 0;"
      , "  for (names = voids[text.length]; *names != '\\0'; names += text.length)"
      , "    if (memcmp(names, text.bytes, text.length) == 0) return 1;"
      , "  return 0;"
      , "}"
      , "/* A suspended list of children: the next to write, and the element name"
      , "   whose closing tag follows them, empty for a fragment's; a written"
      , "   element's name is never empty. */"
      , "typedef struct { pudu_items *items; size_t next; pudu_text close; pudu_box *capture; size_t start; } pudu_html_frame;"
      , "/* Subtrees rendered before, by address. A subtree seen a second time is"
      , "   rendered once more and kept with a reference, so its address cannot be"
      , "   reused while kept; values never change, so a kept rendering is always"
      , "   the subtree's own. The seen table holds no references: an address"
      , "   reused by another subtree only means that subtree is rendered and kept. */"
      , "enum { PUDU_HTML_KEPT = 256, PUDU_HTML_SEEN = 1024, PUDU_HTML_KEPT_BYTES = 64 };"
      , "typedef struct { pudu_box *box; pudu_text text; } pudu_html_kept;"
      , "static _Thread_local pudu_html_kept pudu_html_kept_cells[PUDU_HTML_KEPT];"
      , "static _Thread_local const pudu_box *pudu_html_seen[PUDU_HTML_SEEN];"
      , "static _Thread_local void (*pudu_html_kept_drop)(pudu_box *);"
      , "static _Thread_local int pudu_html_kept_arranged;"
      , "static size_t pudu_html_slot(const pudu_box *box, size_t size) {"
      , "  uintptr_t at = (uintptr_t)box;"
      , "  return (size_t)((at >> 4) ^ (at >> 13)) & (size - 1);"
      , "}"
      , "static void pudu_html_release_kept(void) {"
      , "  for (size_t i = 0; i < PUDU_HTML_KEPT; ++i) {"
      , "    if (pudu_html_kept_cells[i].box == NULL) continue;"
      , "    pudu_html_kept_drop(pudu_html_kept_cells[i].box);"
      , "    pudu_text_release(pudu_html_kept_cells[i].text);"
      , "    pudu_html_kept_cells[i].box = NULL;"
      , "  }"
      , "}"
      , "/* Keeps the bytes a captured subtree wrote, replacing what its slot held. */"
      , "static void pudu_html_keep(pudu_html_writer *out, pudu_box *view, size_t start) {"
      , "  size_t length = out->length - start;"
      , "  pudu_html_kept *kept = &pudu_html_kept_cells[pudu_html_slot(view, PUDU_HTML_KEPT)];"
      , "  unsigned char *bytes;"
      , "  if (length < PUDU_HTML_KEPT_BYTES) return;"
      , "  if (!pudu_html_kept_arranged) {"
      , "    if (atexit(pudu_html_release_kept) != 0) pudu_memory_failure();"
      , "    pudu_html_kept_arranged = 1;"
      , "  }"
      , "  if (kept->box != NULL) { out->drop(kept->box); pudu_text_release(kept->text); }"
      , "  kept->text = pudu_text_allocate(length, &bytes);"
      , "  memcpy(bytes, out->owner->bytes + start, length);"
      , "  kept->box = pudu_box_retain(view);"
      , "  pudu_html_kept_drop = out->drop;"
      , "}"
      , "typedef struct { pudu_html_frame *frames; size_t length, capacity; } pudu_html_stack;"
      , "static void pudu_html_enter(pudu_html_stack *stack, pudu_box *children, pudu_text close, pudu_box *capture, size_t start) {"
      , "  if (stack->length == stack->capacity) {"
      , "    size_t capacity = stack->capacity == 0 ? 16 : stack->capacity * 2;"
      , "    if (capacity > SIZE_MAX / sizeof(pudu_html_frame)) pudu_memory_failure();"
      , "    stack->frames = realloc(stack->frames, capacity * sizeof(pudu_html_frame));"
      , "    if (stack->frames == NULL) pudu_memory_failure();"
      , "    stack->capacity = capacity;"
      , "  }"
      , "  stack->frames[stack->length].items = children->fields[0].items;"
      , "  stack->frames[stack->length].next = 0;"
      , "  stack->frames[stack->length].close = close;"
      , "  stack->frames[stack->length].capture = capture;"
      , "  stack->frames[stack->length].start = start;"
      , "  stack->length += 1;"
      , "}"
      , "/* One node; an element or fragment with children enters them instead of"
      , "   recursing, so nesting depth is bounded by memory, not the call stack. */"
      , "static void pudu_html_put(pudu_html_writer *out, pudu_html_stack *stack, pudu_box *view) {"
      , "  int tag = view->fields[0].scalar;"
      , "  pudu_text none = {0};"
      , "  if (tag == out->text_tag) pudu_html_escape(out, view->fields[1].text);"
      , "  else if (tag == out->trusted_tag) pudu_html_write(out, view->fields[1].text.bytes, view->fields[1].text.length);"
      , "  else {"
      , "    pudu_html_kept *kept = &pudu_html_kept_cells[pudu_html_slot(view, PUDU_HTML_KEPT)];"
      , "    const pudu_box **seen = &pudu_html_seen[pudu_html_slot(view, PUDU_HTML_SEEN)];"
      , "    pudu_box *capture = *seen == view ? view : NULL;"
      , "    size_t start = out->length;"
      , "    if (kept->box == view) { pudu_html_write(out, kept->text.bytes, kept->text.length); return; }"
      , "    *seen = view;"
      , "    if (tag == out->fragment_tag) { pudu_html_enter(stack, view->fields[1].box, none, capture, start); return; }"
      , "  {"
      , "    pudu_text name = view->fields[1].text;"
      , "    pudu_items *attributes;"
      , "    if (!pudu_html_name(name)) { pudu_html_enter(stack, view->fields[3].box, none, NULL, 0); return; }"
      , "    pudu_html_write(out, \"<\", 1);"
      , "    pudu_html_write(out, name.bytes, name.length);"
      , "    attributes = view->fields[2].box->fields[0].items;"
      , "    for (size_t i = 0; i < attributes->length; ++i) {"
      , "      pudu_box *entry = attributes->cells[i].box;"
      , "      pudu_text key = entry->fields[0].text;"
      , "      if (!pudu_html_name(key) || pudu_html_handler(key)) continue;"
      , "      pudu_html_write(out, \" \", 1);"
      , "      pudu_html_write(out, key.bytes, key.length);"
      , "      pudu_html_write(out, \"=\\\"\", 2);"
      , "      pudu_html_escape(out, entry->fields[1].text);"
      , "      pudu_html_write(out, \"\\\"\", 1);"
      , "    }"
      , "    if (pudu_html_void(name)) { pudu_html_write(out, \" />\", 3); return; }"
      , "    pudu_html_write(out, \">\", 1);"
      , "    pudu_html_enter(stack, view->fields[3].box, name, capture, start);"
      , "  }"
      , "  }"
      , "}"
      , "static void pudu_html_walk(pudu_html_writer *out, pudu_box *view) {"
      , "  pudu_html_stack stack = {NULL, 0, 0};"
      , "  pudu_html_put(out, &stack, view);"
      , "  while (stack.length != 0) {"
      , "    pudu_html_frame *top = &stack.frames[stack.length - 1];"
      , "    if (top->next == top->items->length) {"
      , "      pudu_text close = top->close;"
      , "      pudu_box *capture = top->capture;"
      , "      size_t start = top->start;"
      , "      stack.length -= 1;"
      , "      if (close.length != 0) {"
      , "        pudu_html_write(out, \"</\", 2);"
      , "        pudu_html_write(out, close.bytes, close.length);"
      , "        pudu_html_write(out, \">\", 1);"
      , "      }"
      , "      if (capture != NULL) pudu_html_keep(out, capture, start);"
      , "    } else {"
      , "      pudu_box *child = top->items->cells[top->next].box;"
      , "      top->next += 1;"
      , "      pudu_html_put(out, &stack, child);"
      , "    }"
      , "  }"
      , "  free(stack.frames);"
      , "}"
      , "/* The page as text; a document starts with its doctype line. */"
      , "static pudu_text pudu_html_render(pudu_box *view, int document, int element_tag, int text_tag, int fragment_tag, int trusted_tag, void (*drop)(pudu_box *)) {"
      , "  pudu_html_writer out = {NULL, 0, 0, text_tag, fragment_tag, trusted_tag, drop};"
      , "  pudu_text text;"
      , "  (void)element_tag;"
      , "  pudu_html_grow(&out, pudu_html_last_length < 256 ? 256 : pudu_html_last_length + pudu_html_last_length / 8);"
      , "  if (document) pudu_html_write(&out, \"<!DOCTYPE html>\\n\", 16);"
      , "  pudu_html_walk(&out, view);"
      , "  pudu_html_last_length = out.length;"
      , "  /* A quarter or more left unused goes back to the allocator. */"
      , "  if (out.capacity - out.length > out.capacity / 4) pudu_html_grow(&out, out.length == 0 ? 1 : out.length);"
      , "  out.owner->count = 1;"
      , "  text.bytes = out.owner->bytes;"
      , "  text.length = out.length;"
      , "  text.owner = out.owner;"
      , "  return text;"
      , "}"
      ])
  ]
